import hashlib
import pathlib
from typing import Any

import pytest

import trudag.dotstop.core.reference as reference
from trudag.dotstop.core.exception import ReferenceError


@pytest.fixture
def example_csv_file(tmp_path: pathlib.Path) -> dict[str, Any]:
    """
    Get the path to a csv file with known sha and markdown interpretation.
    """
    reference_path = tmp_path / "data.csv"
    reference_contents = "header 1,header 2\ndata 1,data 2\ndata 3,data 4\n"
    with reference_path.open("w") as reference_file:
        reference_file.write(reference_contents)
    hash = hashlib.sha256()
    hash.update(str.encode(reference_contents))
    return {
        "type": "file",
        "path": reference_path,
        "sha": hash.hexdigest(),
        "markdown": (
            "| header 1   | header 2   |\n"
            "|------------|------------|\n"
            "| data 1     | data 2     |\n"
            "| data 3     | data 4     |\n"
        ),
    }


@pytest.fixture
def example_bin_file(tmp_path: pathlib.Path) -> dict[str, Any]:
    """
    Get the path to a bin file with known sha but unknown markdown interpretation.
    """
    reference_path = tmp_path / "data.bin"
    reference_contents = "42"
    with reference_path.open("w") as reference_file:
        reference_file.write(reference_contents)
    hash = hashlib.sha256()
    hash.update(str.encode(reference_contents))
    return {
        "type": "file",
        "path": reference_path,
        "sha": hash.hexdigest(),
        "markdown": str(reference_path),
    }


